//! Golden tests of `dstore-gocompat` `strconv` and `time` against `gocompat/numtime.json`, generated by
//! `tools/vectorgen/family_gocompat_numtime.go` from go1.26.5 (schema: `tools/vectorgen/docs/gocompat-b.md`).

use std::sync::OnceLock;

use dstore_gocompat::strconv::{self, NumError, NumErrorKind};
use dstore_gocompat::time::{self as gotime, FixedZone, GoTime};
use dstore_testkit::golden::{decimal_i64, decimal_u64, load_json};
use serde::Deserialize;

#[derive(Deserialize)]
struct BoolCase {
    #[serde(rename = "in")]
    input: String,
    value: bool,
    err: String,
}

#[derive(Deserialize)]
struct IntCase {
    #[serde(rename = "in")]
    input: String,
    base: u32,
    bit_size: u32,
    #[serde(deserialize_with = "decimal_i64")]
    value: i64,
    err: String,
}

#[derive(Deserialize)]
struct UintCase {
    #[serde(rename = "in")]
    input: String,
    base: u32,
    bit_size: u32,
    #[serde(deserialize_with = "decimal_u64")]
    value: u64,
    err: String,
}

#[derive(Deserialize)]
struct FloatCase {
    #[serde(rename = "in")]
    input: String,
    #[serde(deserialize_with = "decimal_u64")]
    bits: u64,
    err: String,
}

#[derive(Deserialize)]
struct FormatFloatCase {
    #[serde(deserialize_with = "decimal_u64")]
    bits: u64,
    out: String,
}

#[derive(Deserialize)]
struct DurStringCase {
    #[serde(deserialize_with = "decimal_i64")]
    ns: i64,
    out: String,
}

#[derive(Deserialize)]
struct DurRoundCase {
    #[serde(deserialize_with = "decimal_i64")]
    ns: i64,
    #[serde(deserialize_with = "decimal_i64")]
    m: i64,
    #[serde(deserialize_with = "decimal_i64")]
    out: i64,
}

#[derive(Deserialize)]
struct ParseDurCase {
    #[serde(rename = "in")]
    input: String,
    #[serde(deserialize_with = "decimal_i64")]
    ns: i64,
    err: String,
}

#[derive(Deserialize)]
struct ZonedCase {
    #[serde(deserialize_with = "decimal_i64")]
    unix_secs: i64,
    nanos: u32,
    offset_secs: i32,
    out: String,
}

#[derive(Deserialize)]
struct UtcCase {
    #[serde(deserialize_with = "decimal_i64")]
    unix_secs: i64,
    nanos: u32,
    out: String,
}

#[derive(Deserialize)]
struct ParseTimeCase {
    #[serde(rename = "in")]
    input: String,
    #[serde(deserialize_with = "decimal_i64")]
    unix_secs: i64,
    nanos: u32,
    err: String,
}

#[derive(Deserialize)]
struct NumtimeFile {
    parse_bool: Vec<BoolCase>,
    parse_int: Vec<IntCase>,
    parse_uint: Vec<UintCase>,
    parse_float: Vec<FloatCase>,
    format_float_g: Vec<FormatFloatCase>,
    duration_string: Vec<DurStringCase>,
    duration_round: Vec<DurRoundCase>,
    parse_duration: Vec<ParseDurCase>,
    rfc3339_local: Vec<ZonedCase>,
    rfc3339nano_utc: Vec<UtcCase>,
    slog_time: Vec<ZonedCase>,
    clock: Vec<ZonedCase>,
    log_std: Vec<ZonedCase>,
    parse_rfc3339nano: Vec<ParseTimeCase>,
}

fn vectors() -> &'static NumtimeFile {
    static FILE: OnceLock<NumtimeFile> = OnceLock::new();
    FILE.get_or_init(|| load_json("gocompat/numtime.json"))
}

/// Collects mismatches, then fails listing the first ones.
struct Mismatches {
    name: &'static str,
    total: usize,
    lines: Vec<String>,
}

impl Mismatches {
    fn new(name: &'static str) -> Mismatches {
        Mismatches {
            name,
            total: 0,
            lines: Vec::new(),
        }
    }

    fn check(&mut self, ok: bool, msg: impl FnOnce() -> String) {
        self.total += 1;
        if !ok {
            self.lines.push(msg());
        }
    }

    fn finish(self) {
        assert!(self.total > 0, "{}: no vectors", self.name);
        assert!(
            self.lines.is_empty(),
            "{}: {} of {} cases differ from Go:\n{}",
            self.name,
            self.lines.len(),
            self.total,
            self.lines[..self.lines.len().min(25)].join("\n")
        );
    }
}

/// The class named by a Go `NumError` text.
fn kind_of(err: &str) -> Option<NumErrorKind> {
    if err.ends_with(": invalid syntax") {
        Some(NumErrorKind::Syntax)
    } else if err.ends_with(": value out of range") {
        Some(NumErrorKind::Range)
    } else {
        None
    }
}

/// The fields of a `NumError` against Go's text (func, input, class), without rendering it.
fn num_error_matches(e: &NumError, func: &str, input: &str, err: &str) -> bool {
    !err.is_empty()
        && e.func == func
        && e.num == input
        && kind_of(err) == Some(e.kind)
        && err.starts_with(&format!("strconv.{func}: parsing "))
}

#[test]
fn parse_bool_values() {
    let mut m = Mismatches::new("parse_bool");
    for c in &vectors().parse_bool {
        let got = strconv::parse_bool(&c.input);
        let ok = match &got {
            Ok(v) => c.err.is_empty() && *v == c.value,
            Err(e) => num_error_matches(e, "ParseBool", &c.input, &c.err),
        };
        m.check(ok, || {
            format!("{:?}: got {got:?}, want {:?} {:?}", c.input, c.value, c.err)
        });
    }
    m.finish();
}

#[test]
fn parse_int_values() {
    let mut m = Mismatches::new("parse_int");
    for c in &vectors().parse_int {
        let got = strconv::parse_int(&c.input, c.base, c.bit_size);
        let ok = match &got {
            Ok(v) => c.err.is_empty() && *v == c.value,
            Err(e) => num_error_matches(e, "ParseInt", &c.input, &c.err),
        };
        m.check(ok, || {
            format!(
                "{:?} base {} bits {}: got {got:?}, want {} {:?}",
                c.input, c.base, c.bit_size, c.value, c.err
            )
        });
    }
    m.finish();
}

