#[test]
fn parse_float_values() {
    let mut m = Mismatches::new("parse_float");
    for c in &vectors().parse_float {
        let got = strconv::parse_float(&c.input);
        let ok = match &got {
            Ok(f) => c.err.is_empty() && f.to_bits() == c.bits,
            Err(e) => num_error_matches(e, "ParseFloat", &c.input, &c.err),
        };
        m.check(ok, || {
            let shown: String = c.input.chars().take(80).collect();
            format!(
                "{shown:?}: got {:?}, want bits {:#018x} {:?}",
                got.map(f64::to_bits),
                c.bits,
                c.err
            )
        });
    }
    m.finish();
}

/// Renders every `NumError` (needs `dstore_gocompat::quote`).
#[test]
fn parse_number_error_texts() {
    let v = vectors();
    let mut m = Mismatches::new("strconv error texts");
    let mut check = |got: Option<String>, want: &str| {
        m.check(got.as_deref().unwrap_or("") == want, || {
            format!("got {got:?}, want {want:?}")
        });
    };
    for c in &v.parse_bool {
        check(
            strconv::parse_bool(&c.input).err().map(|e| e.to_string()),
            &c.err,
        );
    }
    for c in &v.parse_int {
        check(
            strconv::parse_int(&c.input, c.base, c.bit_size)
                .err()
                .map(|e| e.to_string()),
            &c.err,
        );
    }
    for c in &v.parse_uint {
        check(
            strconv::parse_uint(&c.input, c.base, c.bit_size)
                .err()
                .map(|e| e.to_string()),
            &c.err,
        );
    }
    for c in &v.parse_float {
        check(
            strconv::parse_float(&c.input).err().map(|e| e.to_string()),
            &c.err,
        );
    }
    m.finish();
}

#[test]
fn format_float_g() {
    let mut m = Mismatches::new("format_float_g");
    for c in &vectors().format_float_g {
        let got = strconv::format_float_g(f64::from_bits(c.bits));
        m.check(got == c.out, || {
            format!("bits {:#018x}: got {got:?}, want {:?}", c.bits, c.out)
        });
    }
    m.finish();
}

