#[test]
fn rfc3339nano_utc() {
    let mut m = Mismatches::new("rfc3339nano_utc");
    for c in &vectors().rfc3339nano_utc {
        let got = gotime::format_rfc3339nano_utc(GoTime {
            unix_secs: c.unix_secs,
            nanos: c.nanos,
        });
        m.check(got == c.out, || {
            format!(
                "{}.{:09}: got {got:?}, want {:?}",
                c.unix_secs, c.nanos, c.out
            )
        });
    }
    m.finish();
}

#[test]
fn parse_rfc3339nano() {
    let mut m = Mismatches::new("parse_rfc3339nano");
    for c in &vectors().parse_rfc3339nano {
        let got = gotime::parse_rfc3339nano(&c.input);
        let ok = match &got {
            Ok(t) => {
                c.err.is_empty()
                    && *t
                        == GoTime {
                            unix_secs: c.unix_secs,
                            nanos: c.nanos,
                        }
            }
            Err(e) => *e == c.err,
        };
        m.check(ok, || {
            format!(
                "{:?}: got {got:?}, want {}.{:09} {:?}",
                c.input, c.unix_secs, c.nanos, c.err
            )
        });
    }
    m.finish();
}
